import bytewax.operators as op
from bytewax.dataflow import Dataflow
from bytewax.connectors.files import FileSource
from bytewax.outputs import DynamicSink, StatelessSinkPartition
from pathlib import Path
from typing import Optional, Tuple, List

flow = Dataflow("sensor_moving_average")

input_path = Path("input.csv")
stream = op.input("read_input", flow, FileSource(input_path))

def parse_line(line: str) -> Optional[Tuple[str, float]]:
    line = line.strip()
    if not line:
        return None
    if "," not in line:
        return None
    try:
        sensor_id, temp_str = line.split(",", 1)
        sensor_id = sensor_id.strip()
        temp_str = temp_str.strip()
        return str(sensor_id), float(temp_str)
    except ValueError:
        return None

parsed_stream = op.filter_map("parse_line", stream, parse_line)

def update_state(state: Optional[Tuple[float, ...]], temp: float) -> Tuple[Tuple[float, ...], float]:
    if state is None:
        state = ()
    new_state = state + (temp,)
    if len(new_state) > 3:
        new_state = new_state[-3:]
    moving_avg = sum(new_state) / len(new_state)
    return new_state, moving_avg

moving_avg_stream = op.stateful_map("moving_average", parsed_stream, update_state)

def format_output(item: Tuple[str, float]) -> str:
    sensor_id, moving_avg = item
    return f"{sensor_id},{moving_avg:.2f}"

formatted_stream = op.map("format_output", moving_avg_stream, format_output)

class SimpleFileSink(DynamicSink[str]):
    def __init__(self, path: Path):
        self._path = path

    def build(self, step_id: str, worker_index: int, worker_count: int) -> StatelessSinkPartition[str]:
        return SimpleFileSinkPartition(self._path)

class SimpleFileSinkPartition(StatelessSinkPartition[str]):
    def __init__(self, path: Path):
        self._f = open(path, "w")

    def write_batch(self, items: List[str]) -> None:
        for item in items:
            self._f.write(item + "\n")
        self._f.flush()

    def close(self) -> None:
        self._f.close()

op.output("write_output", formatted_stream, SimpleFileSink(Path("test_dynamic_out.csv")))
